const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px;padding:10px;overflow:hidden;background:transparent;color:var(--ink);font:13px/1.4 -apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif}\n.card[data-size=\"3x3\"]{padding:8px;gap:5px;font-size:12px}\n.card[data-size=\"6x6\"],.card[data-size=\"3x6\"]{padding:12px;gap:8px}\n.card *{box-sizing:border-box;min-width:0;overflow-wrap:anywhere}\n.card button{font:inherit;color:inherit;cursor:pointer;text-align:left}\n\n.head{flex:none;display:flex;align-items:center;gap:6px;min-height:30px}\n.ttl{flex:1 1 0;display:flex;align-items:center;gap:5px;font-size:15px;font-weight:800;overflow:hidden;background:none;border:0;padding:0;min-height:30px}\n.ttl.link{cursor:pointer}\n.card[data-size=\"3x3\"] .ttl{font-size:14px}\n.tt{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.pen{flex:none;color:var(--muted);font-size:12px}\n.pg{flex:none;font-size:11px;font-weight:600;color:var(--muted)}\n.ib{flex:none;display:grid;place-items:center;width:30px;height:30px;padding:0;border:1px solid var(--line);border-radius:9px;background:var(--panel-paper);color:var(--ink);font-size:17px;line-height:1;text-align:center}\n.ib:disabled{opacity:.35;cursor:default}\n.sub{flex:none;margin-top:-3px;font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n\n.btn{flex:none;min-height:28px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:12px;font-weight:700;white-space:nowrap;text-align:center}\n.btn.primary{background:var(--accent);border-color:transparent;color:var(--on-accent)}\n.btn:disabled{opacity:.5;cursor:default}\n.card[data-size=\"3x3\"] .head .btn{padding:0 8px}\n\n.body{flex:1 1 0;min-height:0;overflow:auto;scrollbar-width:thin}\n.empty{display:flex;flex-direction:column;justify-content:center;gap:4px;padding:4px 6px;color:var(--muted)}\n.empty p{margin:0}\n.empty .big{font-size:14px;font-weight:800;color:var(--ink)}\n.empty .hint{font-size:12px}\n.err{flex:none;padding:5px 8px;border:1px dashed var(--ink);border-radius:8px;font-size:12px;font-weight:600}\n\n.vlist{display:grid;grid-template-columns:minmax(0,1fr);gap:6px;align-content:start}\n.card[data-size=\"6x3\"] .vlist{grid-template-columns:repeat(2,minmax(0,1fr))}\n.vrow{display:flex;flex-direction:column;gap:2px;padding:7px 10px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.vrow.has{border-left:4px solid var(--accent)}\n.vname{font-weight:800;font-size:14px;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.vsub{font-size:11px;color:var(--muted)}\n.vpick{font-size:12px;font-weight:600;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.vnote{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card[data-size=\"3x3\"] .vnote{display:none}\n.card[data-size=\"3x3\"] .vpick{-webkit-line-clamp:1}\n\n\n/* \u65b9\u6848\u5217\u8868\u4e0e\u5361\u7247 */\n.plans{display:flex;flex-direction:column;gap:8px}\n.card[data-size=\"6x6\"] .plans{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start;align-items:stretch}\n.card[data-size=\"6x3\"] .plans{flex-direction:row;align-items:stretch;overflow-x:auto;overflow-y:hidden;padding-bottom:4px}\n.plan{flex:none;display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid var(--line);border-radius:12px;background:var(--panel-paper)}\n.plan.picked,.mini.picked{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent);background:var(--soft)}\n.ph{display:flex;align-items:center;gap:6px}\n.no{font-size:12px;font-weight:800;color:var(--muted)}\n.picked .no{color:var(--ink)}\n.badge{margin-left:auto;flex:none;padding:1px 8px;border-radius:99px;background:var(--accent);color:var(--on-accent);font-size:11px;font-weight:800;white-space:nowrap}\n.tag{margin-left:auto;flex:none;padding:0 7px;border:1px dashed var(--line);border-radius:99px;font-size:11px;color:var(--muted);white-space:nowrap}\n.thumb{aspect-ratio:16/9;display:grid;place-items:center;text-align:center;padding:8px;border:1px solid var(--line);border-radius:8px;background:var(--soft)}\n.picked .thumb{background:var(--panel-paper)}\n.hook{font-size:17px;font-weight:900;line-height:1.25}\n.thumb.empty .hook{font-size:12px;font-weight:500;color:var(--muted)}\n.fs{display:flex;flex-direction:column;gap:5px}\n.f{display:flex;flex-direction:column;gap:1px}\n.k{font-size:11px;color:var(--muted)}\n.v{font-size:13px;white-space:pre-wrap}\n.v.none{color:var(--muted)}\n.acts{display:flex;flex-wrap:wrap;gap:4px;margin-top:auto}\n.acts .btn{flex:1 1 0;padding:0 4px}\n.acts>.btn:first-child{flex:1 1 100%}\n.acts.conf>.btn:first-child{flex:1 1 0}\n.cmsg{flex:1 1 100%;font-size:12px;font-weight:600}\n\n.mini{display:flex;flex-direction:column;gap:3px;padding:7px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink)}\n.mtop{display:flex;align-items:center;gap:6px}\n.mhook{font-size:15px;font-weight:900;line-height:1.25;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}\n.mtitle{font-size:12px;color:var(--muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.card[data-size=\"3x3\"] .mini{flex:none;padding:5px 8px;gap:1px}\n.card[data-size=\"3x3\"] .mhook{font-size:13px;-webkit-line-clamp:1}\n.card[data-size=\"3x3\"] .mtitle{-webkit-line-clamp:1}\n.card[data-size=\"6x3\"] .mini{flex:0 0 150px}\n.card[data-size=\"6x3\"] .mhook{-webkit-line-clamp:2}\n\n/* \u8be6\u60c5\uff08\u5c0f\u5c3a\u5bf8\u70b9\u5f00\u67d0\u5957\u65b9\u6848\uff09 */\n.one{display:flex;flex-direction:column}\n.card[data-size=\"3x3\"] .hook{font-size:14px}\n.card[data-size=\"3x3\"] .plan{padding:6px;gap:5px}\n.card[data-size=\"3x3\"] .thumb{padding:6px}\n.card[data-size=\"6x3\"] .plan{display:grid;grid-template-columns:150px minmax(0,1fr);grid-template-areas:\"ph ph\" \"thumb fs\" \"acts acts\";gap:5px 10px;padding:6px 8px}\n.card[data-size=\"6x3\"] .ph{grid-area:ph}\n.card[data-size=\"6x3\"] .thumb{grid-area:thumb;align-self:start}\n.card[data-size=\"6x3\"] .fs{grid-area:fs}\n.card[data-size=\"6x3\"] .acts{grid-area:acts}\n.card[data-size=\"6x3\"] .acts>.btn:first-child{flex:1 1 0}\n.card[data-size=\"6x3\"] .acts.conf>.cmsg{flex:2 1 0}\n\n/* \u8868\u5355 */\n.fields{display:flex;flex-direction:column;gap:8px}\n.lab{display:flex;flex-direction:column;gap:3px}\n.lk{display:flex;justify-content:space-between;align-items:baseline;gap:6px;font-size:12px;font-weight:700;color:var(--muted)}\n.lc{font-weight:500}\n.in{width:100%;min-height:30px;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);font:inherit;line-height:1.4}\n.in:focus{outline:2px solid var(--accent);outline-offset:1px}\n.in::placeholder{color:var(--muted)}\n.area{resize:none;min-height:60px}\n.dz{display:flex;flex-direction:column;gap:6px;margin-top:4px;padding-top:8px;border-top:1px dashed var(--line)}\n.foot{flex:none;display:flex;justify-content:flex-end;gap:6px}\n.foot .btn{min-width:64px}\n";
function norm(s){
  const base=(s&&typeof s==='object')?s:{};
  const vs=Array.isArray(base.videos)?base.videos:[];
  return Object.assign({},base,{videos:vs.map(function(v){
    const ps=Array.isArray(v.plans)?v.plans:[];
    return Object.assign({},v,{plans:ps.map(function(p,i){return Object.assign({no:i+1},p)})});
  })});
}
function chars(t){return Array.from(String(t||'')).length}
function mapV(s,id,fn){
  const n=norm(s);
  return Object.assign({},n,{videos:n.videos.map(function(v){return v.id===id?fn(v):v})});
}
function maxNo(v){return v.plans.reduce(function(m,p){return Math.max(m,p.no||0)},0)}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,size}=ctx;
  const S=norm(state);
  const sz=size||'6x6';
  const compact=(sz==='3x3'||sz==='6x3');
  if(!ui.view)ui.view='list';
  let scroller=null;

  const E=(tag,attrs,...kids)=>{
    const out=[];
    kids.forEach(k=>{(Array.isArray(k)?k:[k]).forEach(x=>{if(x!==null&&x!==undefined&&x!==false)out.push(x)})});
    return el(tag,attrs||{},...out);
  };
  const getV=id=>S.videos.find(v=>v.id===id);
  const go=patch=>{ui.err='';ui.confirm=null;ui.sc=null;Object.assign(ui,patch);redraw()};
  const fail=()=>{ui.busy=false;ui.err='没有保存成功，请再试一次';redraw()};
  const safe=p=>{p.catch(fail)};
  const btn=(label,cls,onclick,extra)=>E('button',Object.assign({type:'button',class:'btn'+(cls?' '+cls:''),onclick:onclick},extra||{}),label);
  const ib=(label,aria,onclick,disabled)=>E('button',{type:'button',class:'ib','aria-label':aria,onclick:onclick,disabled:!!disabled},label);
  const errBar=()=>ui.err?E('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;


  /* ---------- 数据动作 ---------- */
  const pickPlan=(vid,pid)=>safe(update(s=>mapV(s,vid,v=>
    Object.assign({},v,{pickedId:v.pickedId===pid?null:pid}))));

  const copyPlan=(vid,pid)=>{
    const nid=uid();
    safe(update(s=>mapV(s,vid,v=>{
      const i=v.plans.findIndex(p=>p.id===pid);
      if(i<0)return v;
      const src=v.plans[i];
      const np={id:nid,no:maxNo(v)+1,title:src.title,hook:src.hook||'',visual:src.visual||''};
      const ps=v.plans.slice();
      ps.splice(i+1,0,np);
      return Object.assign({},v,{plans:ps});
    })));
  };

  const removePlan=(vid,pid)=>{
    ui.confirm=null;
    if(ui.view==='detail')ui.view='video';
    safe(update(s=>mapV(s,vid,v=>Object.assign({},v,{
      plans:v.plans.filter(p=>p.id!==pid),
      pickedId:v.pickedId===pid?null:v.pickedId
    }))));
  };

  const removeVideo=vid=>{
    ui.confirm=null;ui.view='list';ui.vid=null;ui.pid=null;ui.draft=null;
    safe(update(s=>{
      const n=norm(s);
      return Object.assign({},n,{videos:n.videos.filter(v=>v.id!==vid)});
    }));
  };

  const saveVideo=()=>{
    if(ui.busy)return;
    const d=ui.draft||{};
    const name=String(d.name||'').trim();
    if(!name){ui.err='请先写视频名称';redraw();return}
    const note=String(d.note||'').trim();
    const isNew=!ui.vid;
    const id=ui.vid||uid();
    ui.busy=true;ui.err='';
    commit(s=>{
      const n=norm(s);
      if(isNew)return Object.assign({},n,{videos:[{id:id,name:name,note:note,plans:[],pickedId:null}].concat(n.videos)});
      return mapV(n,id,v=>Object.assign({},v,{name:name,note:note}));
    },{view:'video',vid:id,pid:null,draft:null,err:'',busy:false,confirm:null}).catch(fail);
  };

  const savePlan=()=>{
    if(ui.busy)return;
    const d=ui.draft||{};
    const title=String(d.title||'').trim();
    const hook=String(d.hook||'').trim();
    const visual=String(d.visual||'').trim();
    if(!title){ui.err='请先写标题';redraw();return}
    const vid=ui.vid,pid=ui.pid||null,nid=pid||uid();
    const back=(ui.from==='detail'&&pid)?'detail':'video';
    ui.busy=true;ui.err='';
    commit(s=>mapV(s,vid,v=>{
      if(pid)return Object.assign({},v,{plans:v.plans.map(p=>p.id===pid?Object.assign({},p,{title:title,hook:hook,visual:visual}):p)});
      return Object.assign({},v,{plans:v.plans.concat([{id:nid,no:maxNo(v)+1,title:title,hook:hook,visual:visual}])});
    }),{view:back,vid:vid,pid:back==='detail'?pid:null,draft:null,err:'',busy:false,confirm:null}).catch(fail);
  };

  const openVideo=id=>{
    const v=id?getV(id):null;
    go({view:'videoForm',vid:id||null,draft:{name:v?v.name:'',note:v&&v.note?v.note:''}});
  };
  const openPlan=(pid,from)=>{
    const v=getV(ui.vid);
    const p=(pid&&v)?v.plans.find(x=>x.id===pid):null;
    go({view:'planForm',pid:pid||null,from:from||'video',
      draft:{title:p?p.title:'',hook:p&&p.hook?p.hook:'',visual:p&&p.visual?p.visual:''}});
  };


  /* ---------- 方案卡片 ---------- */
  function planFull(v,p){
    const picked=v.pickedId===p.id;
    const conf=ui.confirm&&ui.confirm.kind==='plan'&&ui.confirm.id===p.id;
    const acts=conf
      ?E('div',{class:'acts conf'},
          E('span',{class:'cmsg'},'删除这套方案？删除后不能恢复。'),
          btn('确认删除','',()=>removePlan(v.id,p.id)),
          btn('取消','',()=>{ui.confirm=null;redraw()}))
      :E('div',{class:'acts'},
          btn(picked?'取消选用':'选用这套',picked?'':'primary',()=>pickPlan(v.id,p.id)),
          btn('编辑','',()=>openPlan(p.id,compact?'detail':'video')),
          btn('复制','',()=>copyPlan(v.id,p.id)),
          btn('删除','',()=>{ui.confirm={kind:'plan',id:p.id};redraw()}));
    return E('article',{class:'plan'+(picked?' picked':'')},
      E('div',{class:'ph'},
        E('span',{class:'no'},'方案 '+p.no),
        picked?E('span',{class:'badge'},'✓ 已选中'):E('span',{class:'tag'},'备选')),
      E('div',{class:'thumb'+(p.hook?'':' empty')},
        E('span',{class:'hook'},p.hook||'未写封面短句')),
      E('div',{class:'fs'},
        E('div',{class:'f'},E('span',{class:'k'},'标题 · '+chars(p.title)+' 字'),E('span',{class:'v'},p.title)),
        E('div',{class:'f'},E('span',{class:'k'},'画面想法'),E('span',{class:'v'+(p.visual?'':' none'),},p.visual||'未写'))),
      acts);
  }

  function mini(v,p){
    const picked=v.pickedId===p.id;
    return E('button',{type:'button',class:'mini'+(picked?' picked':''),
        onclick:()=>go({view:'detail',pid:p.id}),'aria-label':'查看方案 '+p.no},
      E('span',{class:'mtop'},E('span',{class:'no'},'方案 '+p.no),picked?E('span',{class:'badge'},'✓ 已选'):null),
      E('span',{class:'mhook'},p.hook||'（未写封面短句）'),
      E('span',{class:'mtitle'},p.title));
  }

  /* ---------- 视图 ---------- */
  function viewList(){
    const head=E('div',{class:'head'},
      E('div',{class:'ttl'},E('span',{class:'tt'},'标题封面备选')),
      btn('＋ 新视频','primary',()=>openVideo(null),{'aria-label':'新增视频'}));
    let body;
    if(!S.videos.length){
      body=E('div',{class:'empty body'},
        E('p',{class:'big'},'还没有视频'),
        E('p',{class:'hint'},'点右上角「＋ 新视频」，再给它存几套标题、封面短句和画面想法。'));
    }else{
      body=E('div',{class:'body vlist'},S.videos.map(v=>{
        const pk=v.plans.find(p=>p.id===v.pickedId);
        const sub=v.plans.length
          ?(v.plans.length+' 套方案 · '+(pk?'已选方案 '+pk.no:'还没选定'))
          :'还没有方案';
        return E('button',{type:'button',class:'vrow'+(pk?' has':''),onclick:()=>go({view:'video',vid:v.id,pid:null})},
          E('span',{class:'vname'},v.name),
          E('span',{class:'vsub'},sub),
          pk?E('span',{class:'vpick'},'✓ '+pk.title):null,
          v.note?E('span',{class:'vnote'},v.note):null);
      }));
    }
    scroller=body;
    return [head,errBar(),body];
  }

  function viewVideo(v){
    const pk=v.plans.find(p=>p.id===v.pickedId);
    const head=E('div',{class:'head'},
      ib('‹','返回视频列表',()=>go({view:'list',vid:null,pid:null})),
      E('button',{type:'button',class:'ttl link',onclick:()=>openVideo(v.id),'aria-label':'编辑视频：'+v.name},
        E('span',{class:'tt'},v.name),E('span',{class:'pen','aria-hidden':'true'},'✎')),
      btn('＋ 方案','primary',()=>openPlan(null,'video')));
    const sub=compact?null:E('div',{class:'sub'},
      v.plans.length?(v.plans.length+' 套方案 · '+(pk?'已选方案 '+pk.no:'还没选定')):'还没有方案');
    let body;
    if(!v.plans.length){
      body=E('div',{class:'empty body'},
        E('p',{class:'big'},'这条视频还没有方案'),
        E('p',{class:'hint'},'点「＋ 方案」，写一套标题、封面短句和画面想法。'));
    }else{
      body=E('div',{class:'body plans'},v.plans.map(p=>compact?mini(v,p):planFull(v,p)));
    }
    scroller=body;
    return [head,sub,errBar(),body];
  }

  function viewDetail(v){
    const i=v.plans.findIndex(p=>p.id===ui.pid);
    if(i<0){ui.view='video';return viewVideo(v)}
    const p=v.plans[i];
    const head=E('div',{class:'head'},
      ib('‹','返回方案列表',()=>go({view:'video',pid:null})),
      E('div',{class:'ttl'},E('span',{class:'tt'},'方案 '+p.no),E('span',{class:'pg'},(i+1)+'/'+v.plans.length)),
      ib('◂','上一套',()=>go({view:'detail',pid:v.plans[i-1].id}),i===0),
      ib('▸','下一套',()=>go({view:'detail',pid:v.plans[i+1].id}),i===v.plans.length-1));
    const body=E('div',{class:'body one'},planFull(v,p));
    scroller=body;
    return [head,errBar(),body];
  }


  /* ---------- 表单 ---------- */
  function inputField(label,key,ph,opts){
    opts=opts||{};
    const d=ui.draft;
    const count=opts.count?E('span',{class:'lc'},chars(d[key])+' 字'):null;
    const onIn=e=>{d[key]=e.target.value;if(count)count.textContent=chars(e.target.value)+' 字'};
    const ctl=opts.area
      ?E('textarea',{class:'in area',rows:opts.rows||3,value:d[key]||'',placeholder:ph,oninput:onIn})
      :E('input',{class:'in',type:'text',value:d[key]||'',placeholder:ph,oninput:onIn,
          onkeydown:e=>{if(e.key==='Enter'){e.preventDefault();if(opts.onEnter)opts.onEnter()}}});
    return E('label',{class:'lab'},E('span',{class:'lk'},E('span',null,label),count),ctl);
  }

  function formShell(title,onBack,fields,onSave){
    const head=E('div',{class:'head'},
      ib('‹','返回',onBack),
      E('div',{class:'ttl'},E('span',{class:'tt'},title)));
    const body=E('div',{class:'body fields'},fields);
    const foot=E('div',{class:'foot'},
      btn('取消','',onBack),
      btn(ui.busy?'保存中…':'保存','primary',onSave,{disabled:!!ui.busy}));
    scroller=body;
    return [head,body,errBar(),foot];
  }

  function viewPlanForm(){
    const back=()=>go({view:(ui.from==='detail'&&ui.pid)?'detail':'video',draft:null});
    const big=!compact;
    return formShell(ui.pid?'编辑方案':'新方案',back,[
      inputField('标题','title','视频标题',{count:true,onEnter:savePlan}),
      inputField('封面短句','hook','封面上放的那一句',{count:true,onEnter:savePlan}),
      inputField('画面想法','visual','封面画面、构图、人物表情…',{area:true,rows:big?5:3})
    ],savePlan);
  }

  function viewVideoForm(){
    const back=()=>go(ui.vid?{view:'video',draft:null}:{view:'list',draft:null});
    const v=ui.vid?getV(ui.vid):null;
    const fields=[
      inputField('视频名称','name','例如：新手第一周做饭',{onEnter:saveVideo}),
      inputField('备注（选填）','note','选题、发布日期等',{area:true,rows:2})
    ];
    if(v){
